const payload = msg.payload;
const cameraName = payload.camera_name || 'Unknown Camera';
const eventType = payload.event || 'detection';
const state = payload.state;

// Only notify on active detection
if (state === 'active') {
    const icon = eventType === 'person' ? '👤' : '🏃';
    msg.payload = {
        type: 'message',
        content: `${icon} *Alert: ${eventType.toUpperCase()} DETECTED*\n` +
                 `📷 Camera: ${cameraName}\n` +
                 `🕒 Time: ${new Date().toLocaleTimeString('ro-RO')}`,
        parse_mode: 'Markdown'
    };

    // Store last event for status command
    const lastEvents = flow.get('camera_last_events') || {};
    lastEvents[cameraName] = {
        type: eventType,
        time: new Date().toISOString()
    };
    flow.set('camera_last_events', lastEvents);

    return msg;
}

return null;

const SLUG_LABELS = {
    interior: 'Interior curte',
    smallGate: 'Poarta mica',
    backyard: 'Spate casa',
    gate2: 'Poarta glisanta 2',
    gate1: 'Poarta glisanta 1',
    fataCasa: 'Fata casa',
    strada: 'Curte strada'
};

function displayName(slug) {
    if (SLUG_LABELS[slug]) return SLUG_LABELS[slug];
    return slug.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2')
        .replace(/\b\w/g, c => c.toUpperCase());
}

function buildDashboardPayload() {
    const healthStore = flow.get('camera_health') || {};
    const lastEvents = flow.get('camera_last_events') || {};
    const eventLog = flow.get('camera_event_log') || [];
    const cameras = Object.keys(healthStore).map(slug => {
        const health = healthStore[slug];
        const name = health.name || displayName(slug);
        const event = lastEvents[name] || lastEvents[slug] || null;
        return {
            slug,
            name,
            state: health.state,
            healthTime: health.time,
            lastEvent: event
        };
    });
    cameras.sort((a, b) => a.name.localeCompare(b.name));
    return [
        { payload: eventLog },
        { payload: { cameras, updatedAt: new Date().toISOString() } }
    ];
}

const topic = msg.topic;
const state = String(msg.payload || '').toLowerCase();
const slug = topic.split('/')[2];
const cameraName = displayName(slug);

const healthStore = flow.get('camera_health') || {};
const prevState = healthStore[slug];

healthStore[slug] = {
    name: cameraName,
    state: state,
    time: new Date().toISOString()
};
flow.set('camera_health', healthStore);

let telegramMsg = null;
if (prevState && prevState.state !== state) {
    const icon = state === 'online' ? '✅' : '❌';
    telegramMsg = {
        topic: topic,
        payload: {
            type: 'message',
            content: `${icon} *Camera Status Change*\n` +
                     `📷 Camera: ${cameraName}\n` +
                     `📊 Status: ${state.toUpperCase()}`,
            parse_mode: 'Markdown'
        }
    };
}

const dashboardMsgs = buildDashboardPayload();
return [telegramMsg, dashboardMsgs[0], dashboardMsgs[1]];

const healthStore = flow.get('camera_health') || {};
const lastEvents = flow.get('camera_last_events') || {};

let statusText = `📷 *TAPO CAMERA SYSTEM STATUS*\n` +
                 `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

const slugs = Object.keys(healthStore);

if (slugs.length === 0) {
    statusText += "_No cameras currently reporting status._";
} else {
    slugs.sort((a, b) => (healthStore[a].name || a).localeCompare(healthStore[b].name || b));
    slugs.forEach(slug => {
        const health = healthStore[slug];
        const name = health.name || slug;
        const event = lastEvents[name] || lastEvents[slug];
        const icon = health.state === 'online' ? '🟢' : '🔴';

        statusText += `${icon} *${name}*\n` +
                      `   • Status: ${health.state.toUpperCase()}\n`;

        if (event) {
            const eventTime = new Date(event.time).toLocaleTimeString('ro-RO');
            statusText += `   • Last ${event.type}: ${eventTime}\n`;
        }

        statusText += `\n`;
    });
}

msg.payload = {
    chatId: msg.telegram.chatId,
    type: 'message',
    content: statusText,
    parse_mode: 'Markdown'
};

return msg;

const payload = msg.payload;
let logEntry = null;

// Determine if it's an event notification or health change
if (msg.topic && msg.topic.includes('event')) {
    // From func_process_camera_event
    const cameraMatch = payload.content.match(/📷 Camera: (.+)/);
    const typeMatch = payload.content.match(/Alert: (.+) DETECTED/);

    logEntry = {
        camera: cameraMatch ? cameraMatch[1] : 'Unknown',
        type: typeMatch ? typeMatch[1].toLowerCase() : 'event',
        message: typeMatch ? `${typeMatch[1]} detected` : 'Motion',
        time: new Date().toISOString(),
        status: 'active'
    };
} else if (msg.topic && msg.topic.includes('health')) {
    // From func_process_camera_health
    const cameraMatch = payload.content.match(/📷 Camera: (.+)/);
    const statusMatch = payload.content.match(/📊 Status: (.+)/);

    logEntry = {
        camera: cameraMatch ? cameraMatch[1] : 'Unknown',
        type: 'health',
        message: statusMatch ? `Camera is ${statusMatch[1]}` : 'Status changed',
        time: new Date().toISOString(),
        status: statusMatch ? statusMatch[1].toLowerCase() : 'unknown'
    };
}

if (!logEntry) return null;

// Update Log in flow context
let eventLog = flow.get('camera_event_log') || [];
eventLog.unshift(logEntry);

// Limit to 50 entries
if (eventLog.length > 50) {
    eventLog = eventLog.slice(0, 50);
}
flow.set('camera_event_log', eventLog);

// Throttle UI updates to prevent excessive re-renders (max once per 300ms)
// This prevents browser hang when many events arrive quickly
const lastUpdate = flow.get('camera_log_last_update') || 0;
const now = Date.now();
const updateInterval = 300; // milliseconds

if (now - lastUpdate >= updateInterval) {
    // Always get the latest state from flow context (in case updates were throttled)
    const latestLog = flow.get('camera_event_log') || [];
    flow.set('camera_log_last_update', now);
    msg.payload = latestLog;
    return msg;
}

// If throttled, don't send now - the next update that passes throttle will send latest state
return null;

